class Range {
  constructor(start, end) { this.start = start; this.end = end; }
  [Symbol.iterator]() {
    let curr = this.start;
    const end = this.end;
    return { next() {
      return curr <= end ? { value: curr++, done: false } : { done: true };
    }};
  }
}
console.log([...new Range(1, 5)]);

